const cart=[];const cartCount=document.getElementById('cart-count');const cartItems=document.getElementById('cart-items');const emptyCart=document.getElementById('empty-cart');document.querySelectorAll('.add').forEach(btn=>btn.addEventListener('click',()=>{cart.push(btn.dataset.name);renderCart();document.body.classList.add('cart-open')}));document.querySelector('.cart-button')?.addEventListener('click',()=>document.body.classList.add('cart-open'));document.querySelector('.close-cart')?.addEventListener('click',()=>document.body.classList.remove('cart-open'));function renderCart(){cartCount.textContent=cart.length;emptyCart.style.display=cart.length?'none':'';cartItems.innerHTML=cart.map(name=>'<div class="cart-item"><strong>'+name+'</strong><span>Qty 1</span></div>').join('')}
